72	UInt64 AsynchronousInsertQueue::InsertQuery::Hash::operator()(const InsertQuery & insert_query) const
73	{
74	    SipHash hash;
75	    insert_query.query->updateTreeHash(hash);
76	
77	    for (const auto & setting : insert_query.settings.allChanged())
78	    {
79	        hash.update(setting.getName());
80	        applyVisitor(FieldVisitorHash(hash), setting.getValue());
81	    }
82	
83	    return hash.get64();
84	}
