123	AsynchronousInsertQueue::AsynchronousInsertQueue(ContextPtr context_, size_t pool_size, size_t max_data_size_, const Timeout & timeouts)
124	    : WithContext(context_)
125	    , max_data_size(max_data_size_)
126	    , busy_timeout(timeouts.busy)
127	    , stale_timeout(timeouts.stale)
128	    , pool(pool_size)
129	    , dump_by_first_update_thread(&AsynchronousInsertQueue::busyCheck, this)
130	    , cleanup_thread(&AsynchronousInsertQueue::cleanup, this)
131	{
132	    using namespace std::chrono;
133	
134	    assert(pool_size);
135	
136	    if (stale_timeout > 0ms)
137	        dump_by_last_update_thread = ThreadFromGlobalPool(&AsynchronousInsertQueue::staleCheck, this);
138	}
