140	AsynchronousInsertQueue::~AsynchronousInsertQueue()
141	{
142	    /// TODO: add a setting for graceful shutdown.
143	
144	    shutdown = true;
145	
146	    assert(dump_by_first_update_thread.joinable());
147	    dump_by_first_update_thread.join();
148	
149	    assert(cleanup_thread.joinable());
150	    cleanup_thread.join();
151	
152	    if (dump_by_last_update_thread.joinable())
153	        dump_by_last_update_thread.join();
154	
155	    pool.wait();
156	
157	    std::lock_guard lock(currently_processing_mutex);
158	    for (const auto & [_, entry] : currently_processing_queries)
159	    {
160	        if (!entry->isFinished())
161	            entry->finish(std::make_exception_ptr(Exception(
162	                ErrorCodes::TIMEOUT_EXCEEDED,
163	                "Wait for async insert timeout exceeded)")));
164	    }
165	}
