167	void AsynchronousInsertQueue::scheduleDataProcessingJob(const InsertQuery & key, InsertDataPtr data, ContextPtr global_context)
168	{
169	    /// Wrap 'unique_ptr' with 'shared_ptr' to make this
170	    /// lambda copyable and allow to save it to the thread pool.
171	    pool.scheduleOrThrowOnError([key, global_context, data = std::make_shared<InsertDataPtr>(std::move(data))]() mutable
172	    {
173	        processData(key, std::move(*data), std::move(global_context));
174	    });
175	}
