382	// static
383	void AsynchronousInsertQueue::processData(InsertQuery key, InsertDataPtr data, ContextPtr global_context)
384	try
385	{
386	    if (!data)
387	        return;
388	
389	    const auto * log = &Poco::Logger::get("AsynchronousInsertQueue");
390	    const auto & insert_query = assert_cast<const ASTInsertQuery &>(*key.query);
391	    auto insert_context = Context::createCopy(global_context);
392	
393	    /// 'resetParser' doesn't work for parallel parsing.
394	    key.settings.set("input_format_parallel_parsing", false);
395	    insert_context->makeQueryContext();
396	    insert_context->setSettings(key.settings);
397	
398	    /// Set initial_query_id, because it's used in InterpreterInsertQuery for table lock.
399	    insert_context->getClientInfo().query_kind = ClientInfo::QueryKind::INITIAL_QUERY;
400	    insert_context->setCurrentQueryId("");
401	
402	    InterpreterInsertQuery interpreter(key.query, insert_context, key.settings.insert_allow_materialized_columns, false, false, true);
403	    auto pipeline = interpreter.execute().pipeline;
404	    assert(pipeline.pushing());
405	
406	    auto header = pipeline.getHeader();
407	    auto format = getInputFormatFromASTInsertQuery(key.query, false, header, insert_context, nullptr);
408	
409	    size_t total_rows = 0;
410	    InsertData::EntryPtr current_entry;
411	
412	    auto on_error = [&](const MutableColumns & result_columns, Exception & e)
413	    {
414	        LOG_ERROR(log, "Failed parsing for query '{}' with query id {}. {}",
415	            queryToString(key.query), current_entry->query_id, e.displayText());
416	
417	        for (const auto & column : result_columns)
418	            if (column->size() > total_rows)
419	                column->popBack(column->size() - total_rows);
420	
421	        current_entry->finish(std::current_exception());
422	        return 0;
423	    };
424	
425	    std::shared_ptr<ISimpleTransform> adding_defaults_transform;
426	    if (insert_context->getSettingsRef().input_format_defaults_for_omitted_fields && insert_query.table_id)
427	    {
428	        StoragePtr storage = DatabaseCatalog::instance().getTable(insert_query.table_id, insert_context);
429	        auto metadata_snapshot = storage->getInMemoryMetadataPtr();
430	        const auto & columns = metadata_snapshot->getColumns();
431	        if (columns.hasDefaults())
432	            adding_defaults_transform = std::make_shared<AddingDefaultsTransform>(header, columns, *format, insert_context);
433	    }
434	
435	    StreamingFormatExecutor executor(header, format, std::move(on_error), std::move(adding_defaults_transform));
436	    std::unique_ptr<ReadBuffer> last_buffer;
437	    for (const auto & entry : data->entries)
438	    {
439	        auto buffer = std::make_unique<ReadBufferFromString>(entry->bytes);
440	        current_entry = entry;
441	        total_rows += executor.execute(*buffer);
442	
443	        /// Keep buffer, because it still can be used
444	        /// in destructor, while resetting buffer at next iteration.
445	        last_buffer = std::move(buffer);
446	    }
447	
448	    format->addBuffer(std::move(last_buffer));
449	
450	    auto chunk = Chunk(executor.getResultColumns(), total_rows);
451	    size_t total_bytes = chunk.bytes();
452	
453	    auto source = std::make_shared<SourceFromSingleChunk>(header, std::move(chunk));
454	    pipeline.complete(Pipe(std::move(source)));
455	
456	    CompletedPipelineExecutor completed_executor(pipeline);
457	    completed_executor.execute();
458	
459	    LOG_INFO(log, "Flushed {} rows, {} bytes for query '{}'",
460	        total_rows, total_bytes, queryToString(key.query));
461	
462	    for (const auto & entry : data->entries)
463	        if (!entry->isFinished())
464	            entry->finish();
465	
466	    CurrentMetrics::sub(CurrentMetrics::PendingAsyncInsert, data->entries.size());
467	}
468	catch (const Exception & e)
469	{
470	    finishWithException(key.query, data->entries, e);
471	}
472	catch (const Poco::Exception & e)
473	{
474	    finishWithException(key.query, data->entries, e);
475	}
476	catch (const std::exception & e)
477	{
478	    finishWithException(key.query, data->entries, e);
479	}
480	catch (...)
481	{
482	    finishWithException(key.query, data->entries, Exception(ErrorCodes::UNKNOWN_EXCEPTION, "Unknown exception"));
483	}
484	
485	template <typename E>
486	void AsynchronousInsertQueue::finishWithException(
487	    const ASTPtr & query, const std::list<InsertData::EntryPtr> & entries, const E & exception)
488	{
489	    tryLogCurrentException("AsynchronousInsertQueue", fmt::format("Failed insertion for query '{}'", queryToString(query)));
490	
491	    for (const auto & entry : entries)
492	    {
493	        if (!entry->isFinished())
494	        {
495	            /// Make a copy of exception to avoid concurrent usage of
496	            /// one exception object from several threads.
497	            entry->finish(std::make_exception_ptr(exception));
498	        }
499	    }
500	
501	    CurrentMetrics::sub(CurrentMetrics::PendingAsyncInsert, entries.size());
502	}
503	
504	}
