14	/// A queue, that stores data for insert queries and periodically flushes it to tables.
15	/// The data is grouped by table, format and settings of insert query.
16	class AsynchronousInsertQueue : public WithContext
17	{
18	public:
19	    using Milliseconds = std::chrono::milliseconds;
20	
21	    /// Using structure to allow and benefit from designated initialization and not mess with a positional arguments in ctor.
22	    struct Timeout
23	    {
24	        Milliseconds busy;
25	        Milliseconds stale;
26	    };
27	
28	    AsynchronousInsertQueue(ContextPtr context_, size_t pool_size, size_t max_data_size, const Timeout & timeouts);
29	    ~AsynchronousInsertQueue();
30	
31	    void push(ASTPtr query, ContextPtr query_context);
32	    void waitForProcessingQuery(const String & query_id, const Milliseconds & timeout);
33	
34	private:
35	
36	    struct InsertQuery
37	    {
38	        ASTPtr query;
39	        Settings settings;
40	
41	        InsertQuery(const ASTPtr & query_, const Settings & settings_);
42	        InsertQuery(const InsertQuery & other);
43	        InsertQuery & operator=(const InsertQuery & other);
44	
45	        bool operator==(const InsertQuery & other) const;
46	        struct Hash { UInt64 operator()(const InsertQuery & insert_query) const; };
47	    };
48	
49	    struct InsertData
50	    {
51	        struct Entry
52	        {
53	        public:
54	            const String bytes;
55	            const String query_id;
56	
57	            Entry(String && bytes_, String && query_id_);
58	
59	            void finish(std::exception_ptr exception_ = nullptr);
60	            bool wait(const Milliseconds & timeout) const;
61	            bool isFinished() const;
62	            std::exception_ptr getException() const;
63	
64	        private:
65	            mutable std::mutex mutex;
66	            mutable std::condition_variable cv;
67	
68	            bool finished = false;
69	            std::exception_ptr exception;
70	        };
71	
72	        using EntryPtr = std::shared_ptr<Entry>;
73	
74	        std::list<EntryPtr> entries;
75	        size_t size = 0;
76	
77	        /// Timestamp of the first insert into queue, or after the last queue dump.
78	        /// Used to detect for how long the queue is active, so we can dump it by timer.
79	        std::chrono::time_point<std::chrono::steady_clock> first_update = std::chrono::steady_clock::now();
80	
81	        /// Timestamp of the last insert into queue.
82	        /// Used to detect for how long the queue is stale, so we can dump it by another timer.
83	        std::chrono::time_point<std::chrono::steady_clock> last_update;
84	    };
85	
86	    using InsertDataPtr = std::unique_ptr<InsertData>;
87	
88	    /// A separate container, that holds a data and a mutex for it.
89	    /// When it's needed to process current chunk of data, it can be moved for processing
90	    /// and new data can be recreated without holding a lock during processing.
91	    struct Container
92	    {
93	        std::mutex mutex;
94	        InsertDataPtr data;
95	    };
96	
97	    using Queue = std::unordered_map<InsertQuery, std::shared_ptr<Container>, InsertQuery::Hash>;
98	    using QueueIterator = Queue::iterator;
99	
100	    mutable std::shared_mutex rwlock;
101	    Queue queue;
102	
103	    using QueryIdToEntry = std::unordered_map<String, InsertData::EntryPtr>;
104	    mutable std::mutex currently_processing_mutex;
105	    QueryIdToEntry currently_processing_queries;
106	
107	    /// Logic and events behind queue are as follows:
108	    ///  - busy_timeout:   if queue is active for too long and there are a lot of rapid inserts, then we dump the data, so it doesn't
109	    ///                    grow for a long period of time and users will be able to select new data in deterministic manner.
110	    ///  - stale_timeout:  if queue is stale for too long, then we dump the data too, so that users will be able to select the last
111	    ///                    piece of inserted data.
112	    ///  - max_data_size:  if the maximum size of data is reached, then again we dump the data.
113	
114	    const size_t max_data_size;  /// in bytes
115	    const Milliseconds busy_timeout;
116	    const Milliseconds stale_timeout;
117	
118	    std::atomic<bool> shutdown{false};
119	    ThreadPool pool;  /// dump the data only inside this pool.
120	    ThreadFromGlobalPool dump_by_first_update_thread;  /// uses busy_timeout and busyCheck()
121	    ThreadFromGlobalPool dump_by_last_update_thread;   /// uses stale_timeout and staleCheck()
122	    ThreadFromGlobalPool cleanup_thread;               /// uses busy_timeout and cleanup()
123	
124	    Poco::Logger * log = &Poco::Logger::get("AsynchronousInsertQueue");
125	
126	    void busyCheck();
127	    void staleCheck();
128	    void cleanup();
129	
130	    /// Should be called with shared or exclusively locked 'rwlock'.
131	    void pushImpl(InsertData::EntryPtr entry, QueueIterator it);
132	
133	    void scheduleDataProcessingJob(const InsertQuery & key, InsertDataPtr data, ContextPtr global_context);
134	    static void processData(InsertQuery key, InsertDataPtr data, ContextPtr global_context);
135	
136	    template <typename E>
137	    static void finishWithException(const ASTPtr & query, const std::list<InsertData::EntryPtr> & entries, const E & exception);
138	
139	public:
140	    auto getQueueLocked() const
141	    {
142	        std::shared_lock lock(rwlock);
143	        return std::make_pair(std::ref(queue), std::move(lock));
144	    }
145	};
146	
