71	    class ParserStorageWithComment : public IParserBase
72	    {
73	    protected:
74	        const char * getName() const override { return "storage definition with comment"; }
75	        bool parseImpl(Pos & pos, ASTPtr & node, Expected & expected) override
76	        {
77	            ParserStorage storage_p;
78	            ASTPtr storage;
79	
80	            if (!storage_p.parse(pos, storage, expected))
81	                return false;
82	
83	            ParserKeyword s_comment("COMMENT");
84	            ParserStringLiteral string_literal_parser;
85	            ASTPtr comment;
86	
87	            if (s_comment.ignore(pos, expected))
88	                string_literal_parser.parse(pos, comment, expected);
89	
90	            auto storage_with_comment = std::make_shared<StorageWithComment>();
91	            storage_with_comment->storage = std::move(storage);
92	            storage_with_comment->comment = std::move(comment);
93	
94	            node = storage_with_comment;
95	            return true;
96	        }
97	    };
