106	/// Creates a system log with MergeTree engine using parameters from config
107	template <typename TSystemLog>
108	std::shared_ptr<TSystemLog> createSystemLog(
109	    ContextPtr context,
110	    const String & default_database_name,
111	    const String & default_table_name,
112	    const Poco::Util::AbstractConfiguration & config,
113	    const String & config_prefix)
114	{
115	    if (!config.has(config_prefix))
116	    {
117	        LOG_DEBUG(&Poco::Logger::get("SystemLog"),
118	                "Not creating {}.{} since corresponding section '{}' is missing from config",
119	                default_database_name, default_table_name, config_prefix);
120	
121	        return {};
122	    }
123	
124	    String database = config.getString(config_prefix + ".database", default_database_name);
125	    String table = config.getString(config_prefix + ".table", default_table_name);
126	
127	    if (database != default_database_name)
128	    {
129	        /// System tables must be loaded before other tables, but loading order is undefined for all databases except `system`
130	        LOG_ERROR(&Poco::Logger::get("SystemLog"), "Custom database name for a system table specified in config."
131	            " Table `{}` will be created in `system` database instead of `{}`", table, database);
132	        database = default_database_name;
133	    }
134	
135	    String engine;
136	    if (config.has(config_prefix + ".engine"))
137	    {
138	        if (config.has(config_prefix + ".partition_by"))
139	            throw Exception("If 'engine' is specified for system table, "
140	                "PARTITION BY parameters should be specified directly inside 'engine' and 'partition_by' setting doesn't make sense",
141	                ErrorCodes::BAD_ARGUMENTS);
142	        if (config.has(config_prefix + ".ttl"))
143	            throw Exception("If 'engine' is specified for system table, "
144	                            "TTL parameters should be specified directly inside 'engine' and 'ttl' setting doesn't make sense",
145	                            ErrorCodes::BAD_ARGUMENTS);
146	        engine = config.getString(config_prefix + ".engine");
147	    }
148	    else
149	    {
150	        String partition_by = config.getString(config_prefix + ".partition_by", "toYYYYMM(event_date)");
151	        engine = "ENGINE = MergeTree";
152	        if (!partition_by.empty())
153	            engine += " PARTITION BY (" + partition_by + ")";
154	        String ttl = config.getString(config_prefix + ".ttl", "");
155	        if (!ttl.empty())
156	            engine += " TTL " + ttl;
157	
158	        engine += " ORDER BY ";
159	        engine += TSystemLog::getDefaultOrderBy();
160	    }
161	
162	    /// Validate engine definition syntax to prevent some configuration errors.
163	    ParserStorageWithComment storage_parser;
164	    parseQuery(storage_parser, engine.data(), engine.data() + engine.size(),
165	            "Storage to create table for " + config_prefix, 0, DBMS_DEFAULT_MAX_PARSER_DEPTH);
166	
167	    size_t flush_interval_milliseconds = config.getUInt64(config_prefix + ".flush_interval_milliseconds",
168	                                                          DEFAULT_SYSTEM_LOG_FLUSH_INTERVAL_MILLISECONDS);
169	
170	    return std::make_shared<TSystemLog>(context, database, table, engine, flush_interval_milliseconds);
171	}
