195	    crash_log = createSystemLog<CrashLog>(global_context, "system", "crash_log", config, "crash_log");
196	    text_log = createSystemLog<TextLog>(global_context, "system", "text_log", config, "text_log");
197	    metric_log = createSystemLog<MetricLog>(global_context, "system", "metric_log", config, "metric_log");
198	    cache_log = createSystemLog<FilesystemCacheLog>(global_context, "system", "filesystem_cache_log", config, "filesystem_cache_log");
199	    asynchronous_metric_log = createSystemLog<AsynchronousMetricLog>(
200	        global_context, "system", "asynchronous_metric_log", config,
201	        "asynchronous_metric_log");
202	    opentelemetry_span_log = createSystemLog<OpenTelemetrySpanLog>(
203	        global_context, "system", "opentelemetry_span_log", config,
204	        "opentelemetry_span_log");
205	    query_views_log = createSystemLog<QueryViewsLog>(global_context, "system", "query_views_log", config, "query_views_log");
206	    zookeeper_log = createSystemLog<ZooKeeperLog>(global_context, "system", "zookeeper_log", config, "zookeeper_log");
207	    session_log = createSystemLog<SessionLog>(global_context, "system", "session_log", config, "session_log");
208	    transactions_info_log = createSystemLog<TransactionsInfoLog>(
209	        global_context, "system", "transactions_info_log", config, "transactions_info_log");
210	    processors_profile_log = createSystemLog<ProcessorsProfileLog>(global_context, "system", "processors_profile_log", config, "processors_profile_log");
211	
212	    if (query_log)
213	        logs.emplace_back(query_log.get());
214	    if (query_thread_log)
215	        logs.emplace_back(query_thread_log.get());
216	    if (part_log)
217	        logs.emplace_back(part_log.get());
218	    if (trace_log)
219	        logs.emplace_back(trace_log.get());
220	    if (crash_log)
221	        logs.emplace_back(crash_log.get());
222	    if (text_log)
223	        logs.emplace_back(text_log.get());
224	    if (metric_log)
225	        logs.emplace_back(metric_log.get());
226	    if (asynchronous_metric_log)
227	        logs.emplace_back(asynchronous_metric_log.get());
228	    if (opentelemetry_span_log)
229	        logs.emplace_back(opentelemetry_span_log.get());
230	    if (query_views_log)
231	        logs.emplace_back(query_views_log.get());
232	    if (zookeeper_log)
233	        logs.emplace_back(zookeeper_log.get());
234	    if (session_log)
235	    {
236	        logs.emplace_back(session_log.get());
237	        global_context->addWarningMessage("Table system.session_log is enabled. It's unreliable and may contain garbage. Do not use it for any kind of security monitoring.");
238	    }
239	    if (transactions_info_log)
240	        logs.emplace_back(transactions_info_log.get());
241	    if (processors_profile_log)
242	        logs.emplace_back(processors_profile_log.get());
243	    if (cache_log)
244	        logs.emplace_back(cache_log.get());
245	
246	    try
247	    {
248	        for (auto & log : logs)
249	            log->startup();
250	    }
251	    catch (...)
252	    {
253	        /// join threads
254	        shutdown();
255	        throw;
256	    }
257	
258	    if (metric_log)
259	    {
260	        size_t collect_interval_milliseconds = config.getUInt64("metric_log.collect_interval_milliseconds",
261	                                                                DEFAULT_METRIC_LOG_COLLECT_INTERVAL_MILLISECONDS);
262	        metric_log->startCollectMetric(collect_interval_milliseconds);
263	    }
264	
265	    if (crash_log)
266	    {
267	        CrashLog::initialize(crash_log);
268	    }
269	}
