311	template <typename LogElement>
312	void SystemLog<LogElement>::savingThreadFunction()
313	{
314	    setThreadName("SystemLogFlush");
315	
316	    std::vector<LogElement> to_flush;
317	    bool exit_this_thread = false;
318	    while (!exit_this_thread)
319	    {
320	        try
321	        {
322	            // The end index (exclusive, like std end()) of the messages we are
323	            // going to flush.
324	            uint64_t to_flush_end = 0;
325	            // Should we prepare table even if there are no new messages.
326	            bool should_prepare_tables_anyway = false;
327	
328	            {
329	                std::unique_lock lock(mutex);
330	                flush_event.wait_for(lock,
331	                    std::chrono::milliseconds(flush_interval_milliseconds),
332	                    [&] ()
333	                    {
334	                        return requested_flush_up_to > flushed_up_to || is_shutdown || is_force_prepare_tables;
335	                    }
336	                );
337	
338	                queue_front_index += queue.size();
339	                to_flush_end = queue_front_index;
340	                // Swap with existing array from previous flush, to save memory
341	                // allocations.
342	                to_flush.resize(0);
343	                queue.swap(to_flush);
344	
345	                should_prepare_tables_anyway = is_force_prepare_tables;
346	
347	                exit_this_thread = is_shutdown;
348	            }
349	
350	            if (to_flush.empty())
351	            {
352	                if (should_prepare_tables_anyway)
353	                {
354	                    prepareTable();
355	                    LOG_TRACE(log, "Table created (force)");
356	
357	                    std::lock_guard lock(mutex);
358	                    is_force_prepare_tables = false;
359	                    flush_event.notify_all();
360	                }
361	            }
362	            else
363	            {
364	                flushImpl(to_flush, to_flush_end);
365	            }
366	        }
367	        catch (...)
368	        {
369	            tryLogCurrentException(__PRETTY_FUNCTION__);
370	        }
371	    }
372	    LOG_TRACE(log, "Terminating");
373	}
