376	template <typename LogElement>
377	void SystemLog<LogElement>::flushImpl(const std::vector<LogElement> & to_flush, uint64_t to_flush_end)
378	{
379	    try
380	    {
381	        LOG_TRACE(log, "Flushing system log, {} entries to flush up to offset {}",
382	            to_flush.size(), to_flush_end);
383	
384	        /// We check for existence of the table and create it as needed at every
385	        /// flush. This is done to allow user to drop the table at any moment
386	        /// (new empty table will be created automatically). BTW, flush method
387	        /// is called from single thread.
388	        prepareTable();
389	
390	        ColumnsWithTypeAndName log_element_columns;
391	        auto log_element_names_and_types = LogElement::getNamesAndTypes();
392	
393	        for (const auto & name_and_type : log_element_names_and_types)
394	            log_element_columns.emplace_back(name_and_type.type, name_and_type.name);
395	
396	        Block block(std::move(log_element_columns));
397	
398	        MutableColumns columns = block.mutateColumns();
399	        for (const auto & elem : to_flush)
400	            elem.appendToBlock(columns);
401	
402	        block.setColumns(std::move(columns));
403	
404	        /// We write to table indirectly, using InterpreterInsertQuery.
405	        /// This is needed to support DEFAULT-columns in table.
406	
407	        std::unique_ptr<ASTInsertQuery> insert = std::make_unique<ASTInsertQuery>();
408	        insert->table_id = table_id;
409	        ASTPtr query_ptr(insert.release());
410	
411	        // we need query context to do inserts to target table with MV containing subqueries or joins
412	        auto insert_context = Context::createCopy(context);
413	        insert_context->makeQueryContext();
414	
415	        InterpreterInsertQuery interpreter(query_ptr, insert_context);
416	        BlockIO io = interpreter.execute();
417	
418	        PushingPipelineExecutor executor(io.pipeline);
419	
420	        executor.start();
421	        executor.push(block);
422	        executor.finish();
423	    }
424	    catch (...)
425	    {
426	        tryLogCurrentException(__PRETTY_FUNCTION__);
427	    }
428	
429	    {
430	        std::lock_guard lock(mutex);
431	        flushed_up_to = to_flush_end;
432	        is_force_prepare_tables = false;
433	        flush_event.notify_all();
434	    }
435	
436	    LOG_TRACE(log, "Flushed system log up to offset {}", to_flush_end);
437	}
