440	template <typename LogElement>
441	void SystemLog<LogElement>::prepareTable()
442	{
443	    String description = table_id.getNameForLogs();
444	
445	    auto table = DatabaseCatalog::instance().tryGetTable(table_id, getContext());
446	    if (table)
447	    {
448	        if (old_create_query.empty())
449	        {
450	            old_create_query = serializeAST(*getCreateTableQueryClean(table_id, getContext()));
451	            if (old_create_query.empty())
452	                throw Exception(ErrorCodes::LOGICAL_ERROR, "Empty CREATE QUERY for {}", backQuoteIfNeed(table_id.table_name));
453	        }
454	
455	        if (old_create_query != create_query)
456	        {
457	            /// Rename the existing table.
458	            int suffix = 0;
459	            while (DatabaseCatalog::instance().isTableExist(
460	                {table_id.database_name, table_id.table_name + "_" + toString(suffix)}, getContext()))
461	                ++suffix;
462	
463	            auto rename = std::make_shared<ASTRenameQuery>();
464	
465	            ASTRenameQuery::Table from;
466	            from.database = table_id.database_name;
467	            from.table = table_id.table_name;
468	
469	            ASTRenameQuery::Table to;
470	            to.database = table_id.database_name;
471	            to.table = table_id.table_name + "_" + toString(suffix);
472	
473	            ASTRenameQuery::Element elem;
474	            elem.from = from;
475	            elem.to = to;
476	
477	            rename->elements.emplace_back(elem);
478	
479	            LOG_DEBUG(
480	                log,
481	                "Existing table {} for system log has obsolete or different structure. Renaming it to {}.\nOld: {}\nNew: {}\n.",
482	                description,
483	                backQuoteIfNeed(to.table),
484	                old_create_query,
485	                create_query);
486	
487	            auto query_context = Context::createCopy(context);
488	            query_context->makeQueryContext();
489	            InterpreterRenameQuery(rename, query_context).execute();
490	
491	            /// The required table will be created.
492	            table = nullptr;
493	        }
494	        else if (!is_prepared)
495	            LOG_DEBUG(log, "Will use existing table {} for {}", description, LogElement::name());
496	    }
497	
498	    if (!table)
499	    {
500	        /// Create the table.
501	        LOG_DEBUG(log, "Creating new table {} for {}", description, LogElement::name());
502	
503	        auto query_context = Context::createCopy(context);
504	        query_context->makeQueryContext();
505	
506	        auto create_query_ast = getCreateTableQuery();
507	        InterpreterCreateQuery interpreter(create_query_ast, query_context);
508	        interpreter.setInternal(true);
509	        interpreter.execute();
510	
511	        table = DatabaseCatalog::instance().getTable(table_id, getContext());
512	
513	        old_create_query.clear();
514	    }
515	
516	    is_prepared = true;
517	}
