519	template <typename LogElement>
520	ASTPtr SystemLog<LogElement>::getCreateTableQuery()
521	{
522	    auto create = std::make_shared<ASTCreateQuery>();
523	
524	    create->setDatabase(table_id.database_name);
525	    create->setTable(table_id.table_name);
526	
527	    auto new_columns_list = std::make_shared<ASTColumns>();
528	
529	    if (const char * custom_column_list = LogElement::getCustomColumnList())
530	    {
531	        ParserColumnDeclarationList parser;
532	        const Settings & settings = getContext()->getSettingsRef();
533	
534	        ASTPtr columns_list_raw = parseQuery(parser, custom_column_list, "columns declaration list", settings.max_query_size, settings.max_parser_depth);
535	        new_columns_list->set(new_columns_list->columns, columns_list_raw);
536	    }
537	    else
538	    {
539	        auto ordinary_columns = LogElement::getNamesAndTypes();
540	        auto alias_columns = LogElement::getNamesAndAliases();
541	
542	        new_columns_list->set(new_columns_list->columns, InterpreterCreateQuery::formatColumns(ordinary_columns, alias_columns));
543	    }
544	
545	    create->set(create->columns_list, new_columns_list);
546	
547	    ParserStorageWithComment storage_parser;
548	
549	    ASTPtr storage_with_comment_ast = parseQuery(
550	        storage_parser, storage_def.data(), storage_def.data() + storage_def.size(),
551	        "Storage to create table for " + LogElement::name(), 0, DBMS_DEFAULT_MAX_PARSER_DEPTH);
552	
553	    StorageWithComment & storage_with_comment = storage_with_comment_ast->as<StorageWithComment &>();
554	
555	    create->set(create->storage, storage_with_comment.storage);
556	    create->set(create->comment, storage_with_comment.comment);
557	
558	    /// Write additional (default) settings for MergeTree engine to make it make it possible to compare ASTs
559	    /// and recreate tables on settings changes.
560	    const auto & engine = create->storage->engine->as<ASTFunction &>();
561	    if (endsWith(engine.name, "MergeTree"))
562	    {
563	        auto storage_settings = std::make_unique<MergeTreeSettings>(getContext()->getMergeTreeSettings());
564	        storage_settings->loadFromQuery(*create->storage);
565	    }
566	
567	    return create;
568	}
