38	void ProcessorProfileLogElement::appendToBlock(MutableColumns & columns) const
39	{
40	    size_t i = 0;
41	
42	    columns[i++]->insert(DateLUT::instance().toDayNum(event_time).toUnderType());
43	    columns[i++]->insert(event_time);
44	    columns[i++]->insert(event_time_microseconds);
45	
46	    columns[i++]->insert(id);
47	    {
48	        Array parent_ids_array;
49	        parent_ids_array.reserve(parent_ids.size());
50	        for (const UInt64 parent : parent_ids)
51	            parent_ids_array.emplace_back(parent);
52	        columns[i++]->insert(parent_ids_array);
53	    }
54	
55	    columns[i++]->insertData(query_id.data(), query_id.size());
56	    columns[i++]->insertData(processor_name.data(), processor_name.size());
57	    columns[i++]->insert(elapsed_us);
58	    columns[i++]->insert(input_wait_elapsed_us);
59	    columns[i++]->insert(output_wait_elapsed_us);
60	}
